import java.util.*;

class Solution {
    public boolean checkSubarraySum(int[] nums, int k) {
        Map<Long, Integer> first = new HashMap<>();
        first.put(0L, -1);              // empty prefix before index 0
        long mod = 0;
        for (int i = 0; i < nums.length; i++) {
            mod = (mod + nums[i]) % k;
            Integer j = first.get(mod);
            if (j != null) {
                if (i - j >= 2) return true; // run (j, i] has length >= 2 and sum % k == 0
            } else {
                first.put(mod, i);           // remember only the earliest index
            }
        }
        return false;
    }
}

