class Solution:
    def checkSubarraySum(self, nums: List[int], k: int) -> bool:
        first = {0: -1}; p = 0
        for i, x in enumerate(nums):
            p = (p + x) % k
            if p in first:
                if i - first[p] >= 2: return True
            else: first[p] = i
        return False

